class Strategy(ABC):
    @abstractmethod
    def act(self, unit: Unit) -> str:
        pass

    @abstractmethod
    def is_valid(self, unit: Unit) -> bool:
        pass

class NormalStrategy:
    def is_valid(self, unit: Unit) -> bool:
        return True

    def act(self, unit: Unit) -> str:
        return unit.attack()

class DefensiveStrategy:
    def is_valid(self, unit: Unit) -> bool:
        return isinstance(unit, CanHeal)

    def act(self, unit: Unit) -> str:
        if not self.is_valid(unit):
            raise ValueError("invalid defensive unit")
        return unit.attack() + " / " + unit.heal()

class InvalidStrategyError(Exception):
    pass

def require_valid(ok: bool) -> None:
    if not ok:
        raise InvalidStrategyError("strategy cannot handle this unit")

Opponent = tuple[UnitFactory, Strategy]

def describe_opponent(opponent: Opponent) -> Unit:
    factory, _strategy = opponent
    return factory.create_base()

