from functools import wraps

def deco(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

from functools import wraps

def minimum(limit: int):
    def decorator(func):
        @wraps(func)
        def wrapper(value: int):
            if value < limit:
                return "too low"
            return func(value)
        return wrapper
    return decorator

def retry(max_attempts: int):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(max_attempts):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    pass
            return "failed"
        return wrapper
    return decorator

